function chart(key='weight'){return U.progressChart(rowsFor('measurements').filter(x=>typeof x.values[key]==='number').reverse(),key,key==='weight'?client().goal_weight:null);}

function nextSessionIndex(p){const names=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'],today=new Date(day()+'T12:00:00').getDay();return p.sessions.map((s,i)=>({i,d:names.includes(s.day)?(names.indexOf(s.day)-today+7)%7:8})).sort((a,b)=>a.d-b.d)[0]?.i||0;}
function coachingWeek(p,c,currentWeek){
 const weekdays=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'],start=new Date(week()+'T12:00:00'),today=day(),end=new Date(start);end.setDate(start.getDate()+6);
 const locale=window.PandaExperience?.get?.().language==='ar'?'ar-AE':'en-GB',localized=value=>locale==='ar-AE'?(window.PandaI18n?.translate(value)||value):value;
 const dayItems=weekdays.map((name,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);const iso=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-'),matches=p.sessions.map((s,index)=>({s,index})).filter(x=>x.s.day===name),active=iso===today;return `<${matches.length?'button type="button"':'div'} class="week-date ${matches.length?'is-training':''} ${active?'is-today':''}" ${matches.length?`data-action="open-training-day" data-index="${matches[0].index}" aria-label="${e(localized(name)+', '+d.toLocaleDateString(locale,{day:'numeric',month:'long'})+': '+matches.map(x=>localized(x.s.name)).join(', '))}"`:''} ${active?'aria-current="date"':''}><span class="week-day-name" aria-hidden="true">${e(name.slice(0,3))}</span><span class="sr-only">${e(name)}</span><strong>${d.getDate()}</strong><span class="week-date-mark" aria-hidden="true">${icon(matches.length?'workouts':'moon')}</span></${matches.length?'button':'div'}>`;}).join('');
 const started=Date.parse(today)>=Date.parse(c.start_date),pct=started?Math.min(100,currentWeek/p.weeks*100):0,range=start.toLocaleDateString(locale,{day:'numeric',month:'short'})+' – '+end.toLocaleDateString(locale,{day:'numeric',month:'short'});
 return `<section class="panel coaching-week"><div class="panel-head"><h2>This week</h2>${link('training','View plan '+icon('arrow'))}</div><div class="week-overview"><div class="week-sessions">${p.sessions.map((s,i)=>`<button type="button" class="week-session" data-action="open-training-day" data-index="${i}"><span class="week-session-number" aria-hidden="true">${String(i+1).padStart(2,'0')}</span><span class="week-session-copy"><strong>${e(s.name.split(' · ')[0])}</strong><span>${e(s.day)} · ${s.exercises.length} exercises</span></span>${icon('arrow')}</button>`).join('')}</div><div class="week-timeline">${ring(pct,(started?currentWeek:0)+'/'+p.weeks,rt('Coaching week','أسبوع التدريب'))}<p class="caption">${rt('Programme timeline','الجدول الزمني للبرنامج')}</p></div></div><details class="details week-extra"><summary>${icon('checkins')}<span>${rt('Week details','تفاصيل الأسبوع')} · ${e(range)}</span></summary><div class="week-intro"><div><p class="eyebrow">YOUR WEEK, IN FOCUS</p><p class="week-date-range">${e(range)}</p></div><span class="week-session-count">${icon('workouts')}<strong>${p.sessions.length}</strong><span>sessions</span></span></div><div class="week-calendar" aria-label="Assigned weekly schedule">${dayItems}</div><div class="programme-meter"><div class="programme-meter-heading"><span>${icon('target')}<span>Coaching week</span></span><strong>${started?String(currentWeek).padStart(2,'0'):'00'}<small> / ${p.weeks}</small></strong></div><div class="programme-track" role="progressbar" aria-label="Programme timeline" aria-valuemin="0" aria-valuemax="${p.weeks}" aria-valuenow="${started?currentWeek:0}" style="--week-count:${Math.min(p.weeks,24)}"><span style="width:${pct}%"></span></div><p class="caption">${started?'Programme timeline':'Programme starts'} · ${date(c.start_date)}</p></div></details><a href="#/checkins" class="week-checkin"><span class="week-checkin-icon">${icon('checkins')}</span><span class="week-checkin-copy"><strong>Weekly check-in</strong>${checkinStatus().replace('>Weekly check-in</span>','>Schedule to be confirmed</span>')}</span>${icon('arrow')}</a></section>`;
}
