async function clientIntakeReopen(id){if(!coach())throw Error('Coach view required.');const c=get('clients',id),x=PandaIntake.find(state,id),r=PandaIntake.reopenable(x,c);if(!c||!r)throw Error(rt('This intake can’t be reopened now.','لا يمكن إعادة فتح هذا الاستبيان الآن.'));
 if(!confirm(r==='reopen'?rt('Reopen '+c.name+'’s intake questionnaire? They can then change their answers and submit it again.','هل تريد إعادة فتح استبيان البداية لـ'+c.name+'؟ سيتمكن بعدها من تعديل إجاباته وإرساله مرة أخرى.'):rt('Open the intake questionnaire for '+c.name+'? They will see it in their portal.','هل تريد فتح استبيان البداية لـ'+c.name+'؟ سيظهر له في بوابته.')))return;
 // Only the status changes: the answers and the server-set fields go back exactly as loaded.
 await S.commit(s=>{const rows=s.client_intake,i=rows.findIndex(row=>row.id===id);if((i<0?null:rows[i].status)!==(x?x.status:null))throw Error(rt('This intake changed. Refresh before reopening it.','تغيّر هذا الاستبيان. حدّث الصفحة قبل إعادة فتحه.'));if(i<0)rows.push({...PandaIntake.blank(id),status:'reopened'});else rows[i]={...rows[i],status:'reopened'};},PandaIntake.REOPEN_LABEL);
 render();clientIntakeModal(id);U.toast(r==='reopen'?rt('Intake reopened. The client can now update and resubmit it.','أُعيد فتح الاستبيان. يمكن للعميل الآن تحديثه وإرساله مرة أخرى.'):rt('Intake opened for the client.','فُتح الاستبيان للعميل.'));}
