function articleModal(id){
 activeArticleId=id;const raw=get('articles',id),a=raw&&articleLocale(raw);if(!a||(a.status!=='published'||a.hidden)&&!coach())throw Error('This article is not published.');
 U.modal(a.title,`<article class="reading-guide" lang="${recipeLanguage()?'ar':'en'}" dir="${recipeLanguage()?'rtl':'ltr'}"><div class="reading-cover ${editorialCovers[a.id]?'has-editorial':''}">${articleVisual(a)}${editorialCovers[a.id]?'':`<span class="photo-label">${icon('education')}<span>PANDA EDUCATION</span></span>`}</div><div class="reading-meta">${tag(a.category)}<span>${a.sections.length} chapters</span></div><p class="reading-lead">${e(a.summary)}</p><nav class="guide-contents" aria-label="In this guide"><p class="eyebrow">IN THIS GUIDE</p>${a.sections.map(([h],i)=>`<button type="button" data-guide-jump="${i}"><span>${String(i+1).padStart(2,'0')}</span><span>${e(h)}</span>${icon('arrow')}</button>`).join('')}</nav>${a.sections.map(([h,b],i)=>`<section class="reading-chapter" data-guide-chapter="${i}" tabindex="-1"><div class="guide-section-heading"><span class="guide-section-index">${String(i+1).padStart(2,'0')}</span><h3>${e(h)}</h3></div>${chapterPhoto(a,i)}<div class="reading-copy">${String(b).split(/\n\s*\n/).filter(Boolean).map(p=>`<p>${e(p).replaceAll('\n','<br>')}</p>`).join('')}</div></section>`).join('')}${a.related_program_id?`<div class="reading-key">${icon('workouts')}<div><strong>Put the guide into practice</strong><p class="caption">Your assigned version includes the exercises, sets and coaching notes to follow.</p><div class="actions section">${link(coach()?'plans':'training',coach()?'View training programmes':'Open my training plan','btn')}</div></div></div>`:''}<div class="reading-finish"><span class="section-symbol">${icon('bookmark')}</span><div><h3>Make it part of your practice</h3><p class="caption">Keep this guide close. Revisit it whenever you need a clear next step.</p></div></div><div class="actions section">${btn('article-read',client().read_articles.includes(id)?'Mark unread':'Mark as read',true,`data-id="${id}"`)}${btn('article-print',icon('download')+' Print / save PDF',false,`data-id="${id}"`)}</div>${a.references?.length?`<details class="guide-references section"><summary>Further reading</summary><ul>${a.references.filter(r=>/^https:\/\//.test(r.url)).map(r=>`<li><a href="${e(r.url)}" target="_blank" rel="noopener noreferrer">${e(r.title)}</a></li>`).join('')}</ul></details>`:''}</article>`);
}
function articleEdit(id){studioArticleEditor(id);}
function packageModal(id){const p=id?get('packages',id):{id:S.id('package'),name:'',weeks:12,price:null,currency:state.brand?.currency||'AED',features:['library']};if(!p)throw Error('Package not found.');U.modal(id?'Edit package':rt('Create package','إنشاء باقة'),form('package',`<div class="form-grid">${field('Package name','name',p.name,'text','required maxlength="80"')}${field('Duration · weeks','weeks',p.weeks,'number','required min="1" max="104" step="1"')}${field('Document price · blank if not set','price',p.price??'','number','min="0" step="0.01"')}${select('Currency','currency',p.currency,['AED','SAR','EUR','USD'].map(x=>[x,x]))}</div><div class="stack section">${['training','library','nutrition','supplements','progress','checkins','activity','education','roadmap'].map(k=>`<label class="check-label"><input type="checkbox" name="feature_${k}" ${p.features.includes(k)||k==='library'?'checked':''} ${k==='library'?'disabled':''}>${e(k[0].toUpperCase()+k.slice(1))}${k==='library'?' · included in every package':''}</label>`).join('')}</div>${actions()}`,p.id));}
function invoiceModal(id){const i=id?get('invoices',id):{number:'TWP-'+new Date().getFullYear()+'-'+String(state.invoices.length+1).padStart(3,'0'),client_id:client().id,date:day(),currency:'AED',lines:[{name:'Online coaching programme',quantity:1,price:0}],discount:0,tax:0,notes:'Payment is arranged separately.'};U.modal(id?'Edit invoice document':'Create invoice document',form('invoice',`<div class="form-grid">${field('Invoice number','number',i.number,'text','required maxlength="80"')}${select('Client','client_id',i.client_id,state.clients.map(c=>[c.id,c.name]))}${field('Invoice date','date',i.date,'date','required')}${select('Currency','currency',i.currency,['AED','SAR','EUR','USD'].map(x=>[x,x]))}${field('Discount · currency amount','discount',i.discount,'number','required min="0" step="0.01"')}${field('Tax rate · % (set manually)','tax',i.tax,'number','required min="0" max="100" step="0.01"')}</div><div class="stack section">${area('Line items — Description | Quantity | Unit price','lines',i.lines.map(l=>[l.name,l.quantity,l.price].join(' | ')).join('\n'),'required rows="5"')}${area('Document notes','notes',i.notes||'','maxlength="3000"')}</div><p class="caption section">This is a manually prepared document. Currency and tax treatment are not inferred from a client’s location.</p>${actions('Save invoice')}`,id));}
function groceryHTML(){const p=get('nutrition_plans',client().nutrition_id),v=p.variants[variantIndex],combined={};v.meals.flatMap(m=>m.items).forEach(x=>combined[x.food_id]=(combined[x.food_id]||0)+x.quantity);return `<p class="muted">${e(v.name)} · one complete day. Multiply quantities only for the number of days you will repeat this variant.</p>${table(['Food','Quantity','Category'],Object.entries(combined).map(([id,q])=>`<tr><td>${e(food(id).name)}</td><td>${n(q,1)} ${e(food(id).unit)}</td><td>${e(food(id).category)}</td></tr>`))}<p class="caption section">Preparation states and count-based units are retained from the food database. Check your cupboard and package sizes before shopping.</p>`;}
function openEditor(type,id,duplicate=false,planType=''){if(!coach())throw Error('Open the coach workspace first.');const cardio=type==='programs'&&(planType==='cardio'||(!!id&&get(type,id)?.plan_type==='cardio'));const blankCardio={id:'',name:'',name_ar:'',weeks:8,status:'draft',version:0,versions:[],plan_type:'cardio',description:'',description_ar:'',notes:'',notes_ar:'',sessions:[{id:S.id('session'),name:'Cardio session 1',day:'Flexible',focus:'',image:'assets/treadmill.webp',exercises:[]}]};const source=get(type,id)||(cardio?blankCardio:state[type].find(x=>type!=='programs'||x.plan_type!=='cardio')||state[type][0]);const p=copy(source);if(duplicate||!id){p.id=S.id(type==='programs'?'plan':'nutrition');p.name=duplicate?source.name+' · individual copy':'New '+(type==='programs'?(cardio?'cardio':'training'):'nutrition')+' plan';p.status='draft';p.version=0;p.versions=[];if(cardio)p.plan_type='cardio';}editor={type,data:p};dirty=duplicate||!id;if(route==='editor')render();else location.hash='/editor';}
function pickerModal(type,i,j,category='',slot=''){picker={type,i,j,category,slot,q:''};const title=type!=='exercise'?'Choose a food':slot==='warmup'?rt('Add a warm-up move','إضافة حركة إحماء'):slot==='cooldown'?rt('Add a cool-down move','إضافة حركة تهدئة'):'Choose an exercise';U.modal(title,`<input type="search" data-picker-search placeholder="Search the full ${type==='exercise'?'exercise catalogue':'food database'}…" aria-label="Search ${type}">${type==='exercise'?`<div class="picker-chips" role="group" aria-label="${rt('Exercise type','نوع التمرين')}">${[['',rt('All','الكل')],...PANDA_EXERCISE_CATEGORIES.map(([k,en,ar])=>[k,rt(en,ar)])].map(([k,label])=>`<button type="button" class="muscle-chip type-chip ${category===k?'selected':''}" data-action="picker-category" data-category="${e(k)}" aria-pressed="${category===k}"><span>${e(label)}</span></button>`).join('')}</div>`:''}<p class="caption section">${type==='exercise'?(slot?rt('Pick a move for this phase, then set reps or time in the plan.','اختر حركة لهذه المرحلة ثم حدد التكرارات أو الوقت في الخطة.'):'Choose an exercise and customise its prescription.'):'Choose a food and set the quantity for this meal.'}</p><div class="picker-results section" id="picker-results"></div>`);pickerResults('');}
function pickerResults(q){picker.q=q;const needle=q.toLowerCase();const records=picker.type==='exercise'?S.exercises().filter(x=>(!picker.category||x.category===picker.category)&&[x.name,x.equipment,x.category,...(x.tags||[]),...(x.muscle_groups||[])].join(' ').toLowerCase().includes(needle)):state.foods.filter(x=>(!x.issue||S.foodReleased(x))&&x.name.toLowerCase().includes(needle));$('#picker-results').innerHTML=records.slice(0,35).map(x=>`<div class="picker-row">${picker.type==='exercise'?`<span class="picker-thumb">${img(x.image_url||'',x.name)}</span>`:''}<div><strong>${e(x.name)}</strong><p class="caption">${picker.type==='exercise'?e([x.category,x.equipment].filter(Boolean).join(' · ')):n(x.portion)+' '+e(x.unit)}</p></div>${btn('picker-add','Add',true,`data-id="${e(x.exercise_id||x.id)}"`)}</div>`).join('')||empty('No matches','Change your search or review a flagged food first.');}


/* Integrated into the existing portal closure. */
let supplementDraft=null,calorieResult=null,calorieClientId='',educationQuery='';
const fibreText=t=>t.fiberKnown===false?rt('Not fully supplied','غير مكتمل'):n(t.fiber||0,1)+' g';
const effortText=x=>x.effort_scale&&typeof x.effort_target==='number'?x.effort_target+' '+x.effort_scale:rt('As coached','حسب توجيه المدرب');
function effortGuide(){U.modal(rt('RIR & RPE explained','شرح RIR وRPE'),`<div class="stack"><p><strong>RIR · Repetitions in reserve</strong><br>How many more repetitions you could complete with the agreed technique at the end of a set.</p><p><strong>RPE · Rating of perceived exertion</strong><br>The perceived difficulty of a set. This portal uses the resistance-training 1–10, RIR-based convention.</p>${table(['RPE','Approximate RIR','Practical meaning'],[['10','0','No more clean repetitions'],['9','1','One clean repetition left'],['8','2','Two clean repetitions left'],['7','3','Three clean repetitions left']].map(row=>'<tr>'+row.map(v=>'<td>'+e(v)+'</td>').join('')+'</tr>'))}<p>Example: 10 reps at 2 RIR means finishing the set of 10 when you estimate you could still perform about two more clean reps. It does not mean doing the extra two.</p><p class="caption">These are estimates, especially for beginners. Lower RPE values are not a precise linear conversion. Pain, dizziness or unsafe technique are reasons to stop, not to chase the target.</p>${btn('article','Read the full training guide',true,'data-id="hub-training"')}</div>`);}

function supplements(){
 const c=client(),today=day(),entries=c.supplements||[];
 const cards=rows=>rows.map(x=>`<article class="panel supplement-card"><div class="panel-head"><h2>${e(x.name)}</h2><span class="caption">${e(PandaCoaching.status(x,today))}</span></div>${info([['Amount',x.dose||'Confirm with your coach'],['Timing',x.timing||'Confirm with your coach'],['Purpose',x.purpose||'Not specified'],...(x.start_date?[['From',date(x.start_date)]]:[]),...(x.end_date?[['Until',date(x.end_date)]]:[])])}${x.notes?`<p class="section wrap-text">${e(x.notes)}</p>`:''}</article>`).join('');
 const current=entries.filter(x=>PandaCoaching.status(x,today)==='Active'),other=entries.filter(x=>!current.includes(x));
 return head(coach()?'Supplement plans':'Your supplement plan','A clear purpose, amount and schedule for each assigned item.',coach()?btn('supplement-edit',icon('plus')+' Edit client plan',true,`data-id="${e(c.id)}"`):btn('article',icon('education')+' Understand supplements',false,'data-id="hub-supplements"'))+
 (coach()?`<div class="supplement-client-picker panel section">${select('Client','supplement_client',c.id,state.clients.map(c=>[c.id,c.name]),'data-supplement-client')}${btn('supplement-catalogue','Supplement reference library')}<p class="caption">Editing this client’s plan changes only their assigned entries. The reference library does not assign a stack automatically.</p></div>`:'')+
 (coach()?supplementTemplateList():'')+(S.online?'':notice('Demo plan only. These sample entries are not a personal recommendation.'))+
 `<div class="panel section"><div class="panel-head"><h2>${coach()?fullname(c):'Assigned by your coach'}</h2>${btn('supplement-print',icon('download')+' Print / save PDF',false,entries.length?'':'disabled')}</div>${c.supplement_plan_name?`<h3 class="section" data-no-translate dir="auto">${e(suppText(c,'supplement_plan_name'))}</h3>`:''}${c.supplement_plan_notes?`<p class="caption section" data-no-translate dir="auto">${e(suppText(c,'supplement_plan_notes'))}</p>`:''}<p>Use only the product and amount reviewed for you. Tell your coach and an appropriate healthcare professional about relevant medicines, conditions or unwanted effects.</p></div><div class="grid two section supplement-grid">${cards(current)||empty('No active supplement plan','Your coach can assign a reviewed plan here.')}</div>${other.length?`<details class="panel section"><summary>Upcoming, paused and completed entries · ${other.length}</summary><div class="grid two section">${cards(other)}</div></details>`:''}`;
}
function supplementCatalogue(){U.modal('Supplement reference library',`${coach()?btn('supplement-reference-new',icon('plus')+' '+rt('New reference','مرجع جديد'),true):''}<p class="muted">A reviewed reference based on the requested natural-bodybuilding topics. No product is essential for everyone. Amounts are entered individually by the coach.</p><div class="supplement-library section">${studioReferences().map(x=>`<article class="supplement-reference"><div class="panel-head"><h3>${e(x.name)}</h3><span class="caption">${e(x.category)}</span></div><p>${e(x.purpose)}</p><p class="caption section">${e(x.notes)}</p>${coach()?btn('supplement-reference-edit','Edit',false,`data-id="${e(x.id)}"`):''}</article>`).join('')}</div><div class="actions section">${btn('article','Read Supplements HQ',true,'data-id="hub-supplements"')}</div>`);}
function supplementBegin(cid){
 if(!coach())throw Error('Coach view required.');
 const c=get('clients',cid);if(!c)throw Error('Create or select a client first.');
 supplementDraft={clientId:cid,original:JSON.stringify(c.supplements),items:copy(c.supplements)};supplementEditor();
}
function supplementCapture(){
 const f=$('[data-form="supplement-plan"],[data-form="supplement-template"]');if(!f||!supplementDraft)return;if(supplementDraft.templateId){supplementDraft.name=f.elements.namedItem('template_name').value;supplementDraft.name_ar=f.elements.namedItem('template_name_ar').value;for(const k of ['summary','summary_ar','notes','notes_ar'])supplementDraft[k]=f.elements.namedItem('template_'+k).value;supplementDraft.status=f.elements.namedItem('template_status').value;}
 for(const el of f.querySelectorAll('[data-supp-field]')){const [i,k]=el.dataset.suppField.split('.');supplementDraft.items[Number(i)][k]=el.value;}
}
function supplementEditor(){
 const d=supplementDraft,c=d.templateId?{id:d.templateId,name:d.name||rt('New template','قالب جديد')}:get('clients',d.clientId);
 const input=(label,i,k,value,extra='')=>field(label,'supp_'+i+'_'+k,value||'',k.endsWith('_date')?'date':'text',`data-supp-field="${i}.${k}" ${extra}`);
 U.modal('Supplement plan · '+c.name,form(d.templateId?'supplement-template':'supplement-plan',`${d.templateId?`<div class="form-grid">${field('Name','template_name',d.name,'text','required maxlength="150"')}${field(rt('Arabic plan name','اسم الخطة بالعربية'),'template_name_ar',d.name_ar||'','text','maxlength="150" dir="rtl"')}${select('Publication status','template_status',d.status,[['draft','Draft'],['published','Published']])}${area(rt('Plan summary','ملخص الخطة'),'template_summary',d.summary||'','maxlength="600"')}${area(rt('Arabic summary','الملخص بالعربية'),'template_summary_ar',d.summary_ar||'','maxlength="600" dir="rtl"')}${area(rt('Plan guidance','إرشادات الخطة'),'template_notes',d.notes||'','maxlength="3000"')}${area(rt('Arabic guidance','الإرشادات بالعربية'),'template_notes_ar',d.notes_ar||'','maxlength="3000" dir="rtl"')}</div>`:''}<p class="caption">${d.templateId?rt("Edit the reusable template. Assigned client copies keep their existing entries.","عدّل القالب القابل لإعادة الاستخدام. تحتفظ نسخ العملاء المخصصة بمحتواها الحالي."):"Save a separate plan for this client. Confirm the product, amount and timing before assigning it. Empty plans are allowed."}</p><div class="supplement-editor-list section">${d.items.map((x,i)=>`<fieldset class="supplement-editor-item"><legend>Entry ${i+1}</legend><div class="form-grid">${input('Product / supplement',i,'name',x.name,'required maxlength="150"')}${input('Amount · include unit',i,'dose',x.dose,'required maxlength="200"')}${input('Timing / frequency',i,'timing',x.timing,'required maxlength="300"')}${select('Status','supp_'+i+'_status',x.status||'active',[['active','Active'],['paused','Paused']],`data-supp-field="${i}.status"`)}${input('Start date · optional',i,'start_date',x.start_date)}${input('End date · optional',i,'end_date',x.end_date)}${input('Purpose',i,'purpose',x.purpose,'maxlength="1000"')}${input(rt('Arabic product name','اسم المنتج بالعربية'),i,'name_ar',x.name_ar,'maxlength="150" dir="rtl"')}${input(rt('Arabic amount','الكمية بالعربية'),i,'dose_ar',x.dose_ar,'maxlength="200" dir="rtl"')}${input(rt('Arabic timing','التوقيت بالعربية'),i,'timing_ar',x.timing_ar,'maxlength="300" dir="rtl"')}${input(rt('Arabic purpose','الغرض بالعربية'),i,'purpose_ar',x.purpose_ar,'maxlength="1000" dir="rtl"')}${input(rt('Arabic guidance','الإرشادات بالعربية'),i,'notes_ar',x.notes_ar,'maxlength="3000" dir="rtl"')}${area('Guidance / cautions','supp_'+i+'_notes',x.notes||'',`data-supp-field="${i}.notes" maxlength="3000"`)}</div><div class="actions section">${btn('supplement-remove','Remove entry',false,`data-index="${i}"`)}</div></fieldset>`).join('')||`<p class="muted">No entries yet. Choose a reference or add a custom entry below.</p>`}</div><div class="panel section"><div class="form-grid">${select('Reference entry','supplement_preset','',[['','Choose a reference'],...studioReferences().filter(x=>x.assignable).map(x=>[x.id,x.name])])}</div><div class="actions section">${btn('supplement-add','Add selected reference')}${btn('supplement-custom','Add custom entry')}</div><p class="caption">Reference entries supply context only. No amount is prefilled.</p></div>${actions(d.templateId?rt('Save template','حفظ القالب'):'Save client supplement plan')}`,c.id));
}
async function supplementSave(f){
 if(!coach()||!supplementDraft||f.dataset.id!==supplementDraft.clientId)throw Error('Reopen the client plan.');
 if(!f.reportValidity())return;
 supplementCapture();const d=copy(supplementDraft);PandaCoaching.supplements(d.items);
 if(d.items.some(x=>!x.dose?.trim()||!x.timing?.trim()))throw Error('Complete the amount and timing for every entry.');
 await S.commit(next=>{const c=next.clients.find(x=>x.id===d.clientId);if(!c||JSON.stringify(c.supplements)!==d.original)throw Error('This plan changed. Reopen it before saving.');c.supplements=d.items;delete c.supplement_template_id;delete c.supplement_template_version;delete c.supplement_plan_name;delete c.supplement_plan_name_ar;delete c.supplement_plan_notes;delete c.supplement_plan_notes_ar;},'Updated client supplement plan');
 supplementDraft=null;U.close();render();U.toast('Client supplement plan saved.');
}
function supplementPrint(){const c=client();printDocument('Supplement plan',`<p class="document-lead">${e(c.name)} · reviewed with your coach</p>${c.supplement_plan_name?`<h2>${e(suppText(c,'supplement_plan_name'))}</h2>`:''}${c.supplements.map(x=>`<section class="document-callout"><h3>${e(x.name)}</h3>${info([['Status',PandaCoaching.status(x,day())],['Amount',x.dose],['Timing',x.timing],['Purpose',x.purpose],['From',x.start_date?date(x.start_date):'Not specified'],['Until',x.end_date?date(x.end_date):'Not specified']])}<p>${e(x.notes)}</p></section>`).join('')}<p>Use only the reviewed product and amount. Inform your healthcare professional about supplements when discussing conditions, medicines or adverse effects.</p>`,c,{kind:'SUPPLEMENT PLAN',reference:day()});}

function calorieActivityOptions(){return PandaCalories.activityRows.map(([value,factor,label])=>[factor,rt(label,{'Sedentary':'جلوس غالباً · تمرين قليل','Light':'خفيف · مشي / 1–3 جلسات','Moderate':'متوسط · حركة منتظمة / 3–5 جلسات','High':'مرتفع · أيام نشطة / 6–7 جلسات','Very high':'مرتفع جداً · عمل بدني وتدريب'}[value])+' · '+factor]);}
function profileActivityField(c){const value=String(c.activity_level||''),options=[['',rt('Choose activity level','اختر مستوى النشاط')],...PandaCalories.activityRows.map(([key,,label])=>[key,rt(label,{'Sedentary':'جلوس غالباً · تمرين قليل','Light':'خفيف · مشي / 1–3 جلسات','Moderate':'متوسط · حركة منتظمة / 3–5 جلسات','High':'مرتفع · أيام نشطة / 6–7 جلسات','Very high':'مرتفع جداً · عمل بدني وتدريب'}[key])])];if(value&&!options.some(x=>x[0]===value))options.push([value,value]);return select(rt('Activity level','مستوى النشاط'),'activity_level',value,options);}
function calorieFields(c){
 const saved=editor?.data.calorie_calculation?.inputs||(c.id&&get('nutrition_plans',c.nutrition_id)?.calorie_calculation?.inputs)||{},factor=PandaCalories.activity(c.activity_level);
 return `<div class="calorie-section-title full"><span>01</span><h3>${rt('Client data','بيانات العميل')}</h3></div>${field(rt('Age · adults only','العمر · للبالغين فقط'),'age',c.age??'','number','required min="18" max="100" step="1" inputmode="numeric"')}${select(rt('Sex · formula coefficient','الجنس · معامل المعادلة'),'coefficient',c.sex==='Female'?-161:c.sex==='Male'?5:'',[['',rt('Choose coefficient','اختر معامل المعادلة')],[5,rt('Male equation (+5)','معادلة الذكور (+5)')],[-161,rt('Female equation (−161)','معادلة الإناث (−161)')]],'required')}${field(rt('Weight · kg','الوزن · كغ'),'weight',c.weight??'','number','required min="20" max="400" step="0.1" inputmode="decimal"')}${field(rt('Height · cm','الطول · سم'),'height',c.height??'','number','required min="100" max="250" step="0.1" inputmode="decimal"')}${select(rt('Activity estimate','تقدير النشاط'),'activity',factor,[['',rt('Choose activity level','اختر مستوى النشاط')],...calorieActivityOptions()],'required')}${select(rt('Goal','الهدف'),'goal',saved.goal||'maintain',[['loss',rt('Fat loss · −20%','خفض الدهون · −20%')],['maintain',rt('Maintenance · 0%','ثبات الوزن · 0%')],['gain',rt('Muscle gain · +10%','بناء العضلات · +10%')],['custom',rt('Custom adjustment','تعديل مخصص')]],'data-calorie-goal')}
 <p class="caption full">${rt('Activity includes daily movement and training. Choose the closest description; session counts are examples.','يشمل النشاط الحركة اليومية والتدريب. اختر الوصف الأقرب؛ أعداد الجلسات أمثلة.')}</p>
 <div class="calorie-section-title full"><span>02</span><h3>${rt('Coach settings','إعدادات المدرب')}</h3></div>${field(rt('Coach adjustment · %','تعديل المدرب · %'),'adjust',saved.adjust??0,'number','required min="-25" max="25" step="1" inputmode="decimal"')}${field(rt('Calorie target override · optional','تخصيص هدف السعرات · اختياري'),'target_override','','number','min="1200" max="10000" step="1" inputmode="numeric"')}${field(rt('Protein multiplier · g/kg','معامل البروتين · غ/كغ'),'protein_factor',saved.protein_factor??2,'number','required min="0.5" max="3.5" step="0.1" inputmode="decimal"')}${field(rt('Fat multiplier · g/kg','معامل الدهون · غ/كغ'),'fat_factor',saved.fat_factor??1,'number','required min="0.3" max="2" step="0.1" inputmode="decimal"')}
 <p class="caption full">${rt('Carbs use the calories left after protein and fat. The multipliers are editable coaching settings.','تُحسب الكربوهيدرات من السعرات المتبقية بعد البروتين والدهون. يمكن للمدرب تعديل المعاملات.')}</p>`;
}
function calorieContext(c){const p=c.id&&get('nutrition_plans',c.nutrition_id);return c.id?`<div class="calorie-profile-note"><strong data-no-translate>${e(c.name)}</strong><p class="caption">${rt('Prefilled from the saved client profile. Edits here apply to this calculation only.','تمت تعبئة البيانات من ملف العميل المحفوظ. تعديلاتك هنا تخص هذه العملية الحسابية فقط.')}</p>${c.activity_level?`<p class="caption">${rt('Profile activity','النشاط في الملف')}: <span data-no-translate>${e(c.activity_level)}</span></p>`:''}${!PandaCalories.activity(c.activity_level)?`<p class="caption">${rt('Choose an activity level; the profile does not contain a recognised level.','اختر مستوى النشاط؛ لا يحتوي الملف على مستوى معروف.')}</p>`:''}${p?`<p class="caption">${rt('Current targets','الأهداف الحالية')}: ${n(p.targets.calories)} kcal · P ${n(p.targets.protein)} / C ${n(p.targets.carbs)} / F ${n(p.targets.fat)} g</p>`:''}</div>`:`<p class="caption">${rt('Manual estimate. Select a client to apply targets.','تقدير يدوي. اختر عميلاً لتطبيق الأهداف.')}</p>`;}
function calculator(id){
 if(!coach())throw Error('Coach view required.');if(editor&&editor.type!=='nutrition_plans')throw Error('Open a nutrition plan.');
 calorieResult=null;calorieClientId=id||client().id||'';const c=get('clients',calorieClientId)||{};
 U.modal(rt('Calorie & macro calculator','حاسبة السعرات والمغذيات'),form('calculator',`<div class="calorie-intro"><span class="section-symbol">${icon('target')}</span><div><p class="eyebrow">TRAIN WITH PANDA</p><p>${rt('Set the daily target. Build the macros around it.','حدد الهدف اليومي واحسب المغذيات بناءً عليه.')}</p></div></div>${editor?`<p class="notice section">${rt('Updates the open nutrition draft','يحدث مسودة التغذية المفتوحة')}: <strong data-no-translate>${e(editor.data.name)}</strong></p>`:''}<div class="section">${select(rt('Client profile','ملف العميل'),'calculator_client',calorieClientId,[['',rt('Manual calculation','حساب يدوي')],...state.clients.map(c=>[c.id,c.name])],'data-calculator-client')}</div><div id="calorie-context" class="section">${calorieContext(c)}</div><div class="form-grid section" id="calorie-fields">${calorieFields(c)}</div><label class="check-label section"><input type="checkbox" name="suitable" required>${rt('General adult planning is appropriate; this is not a pregnancy, breastfeeding or clinical nutrition prescription.','هذا التقدير مناسب للتخطيط العام للبالغين؛ وليس وصفة للحمل أو الرضاعة أو التغذية العلاجية.')}</label>${actions(rt('Calculate targets','احسب الأهداف'))}<div id="calculator-result" class="section" aria-live="polite"></div><details class="section"><summary>${rt('Method & data sources','الطريقة ومصادر البيانات')}</summary><p>${rt('Mifflin–St Jeor resting energy × activity factor × goal adjustment. Age, sex, height and weight come from the saved profile, not the imagery preference. New measurements do not silently replace profile weight.','طاقة الراحة وفق ميفلين سانت جيور × معامل النشاط × تعديل الهدف. يؤخذ العمر والجنس والطول والوزن من الملف المحفوظ، وليس من تفضيل الصور. لا تستبدل القياسات الجديدة وزن الملف تلقائياً.')}</p><p>${rt('An estimate for coach review. Compare the target with progress over time. The 1,200 kcal software limit is not a guarantee of individual suitability.','تقدير لمراجعة المدرب. قارن الهدف بالتقدم بمرور الوقت. حد البرنامج البالغ 1,200 سعرة لا يضمن الملاءمة لكل فرد.')}</p><a href="https://pubmed.ncbi.nlm.nih.gov/2305711/" target="_blank" rel="noopener noreferrer" class="text-link">Mifflin et al. (1990)</a></details>`));
 $('#modal').classList.add('calorie-dialog');
}
function calculateForm(f){
 if(!coach())throw Error('Coach view required.');const data=Object.fromEntries(new FormData(f)),result=PandaCalories.calculate(data),c=get('clients',calorieClientId),p=c&&get('nutrition_plans',c.nutrition_id);
 calorieResult={...result,signature:JSON.stringify(data),clientId:calorieClientId,originalPlan:p?JSON.stringify(p):null,originalProfile:c?JSON.stringify(c):null};
 const canApply=!!c&&p?.status==='published'&&get('packages',c.package_id)?.features.includes('nutrition');
 $('#calculator-result').innerHTML=`<section class="calorie-results"><div class="calorie-section-title"><span>03</span><h3>${rt('Daily targets','الأهداف اليومية')}</h3></div><div class="calorie-energy"><div><span class="caption">${rt('Calorie target','هدف السعرات')}</span><strong data-calorie-output="target">${n(result.target)}</strong><span>kcal / ${rt('day','يوم')}</span></div><dl><div><dt>${rt('Resting energy · BMR','طاقة الراحة · BMR')}</dt><dd data-calorie-output="resting">${n(result.resting)} kcal</dd></div><div><dt>${rt('Maintenance · TDEE','المحافظة · TDEE')}</dt><dd data-calorie-output="maintenance">${n(result.maintenance)} kcal</dd></div></dl></div><div class="calorie-macros">${[['protein',rt('Protein','البروتين'),'workouts'],['fat',rt('Fat','الدهون'),'water'],['carbs',rt('Carbs','الكربوهيدرات'),'energy']].map(([key,label,symbol])=>`<div>${icon(symbol)}<span>${label}</span><strong data-calorie-output="${key}">${n(result[key])}<small> g</small></strong></div>`).join('')}</div><p class="caption">${rt('Rounded to whole kcal and grams; macro energy can differ by a few kcal.','تم التقريب إلى سعرات وغرامات كاملة؛ قد تختلف طاقة المغذيات ببضع سعرات.')}</p>${result.input.target_override?`<p class="caption">${rt('Formula estimate','تقدير المعادلة')}: ${n(result.estimated)} kcal · ${rt('Coach override applied','تم تطبيق تخصيص المدرب')}</p>`:''}</section><p class="caption section">${rt('Applying updates calories, protein, fat and carbs. Meals, portions, water and fiber stay as planned; review meal totals against the new targets.','يحدث التطبيق السعرات والبروتين والدهون والكربوهيدرات. تبقى الوجبات والحصص والماء والألياف كما خُطط لها؛ راجع إجمالي الوجبات مقارنة بالأهداف الجديدة.')}</p><div class="actions section">${editor?btn('apply-calories',rt('Use in this nutrition draft','استخدم في مسودة التغذية'),true):btn('apply-calories',rt('Apply targets to this client','طبّق الأهداف لهذا العميل'),true,canApply?'':'disabled')}${!editor&&c&&p?btn('calorie-draft',rt('Review as nutrition draft','راجع كمسودة تغذية')):''}</div>${!editor&&c&&!canApply?`<p class="caption">${rt('Direct application needs nutrition access and a published assigned plan. You can prepare a draft first.','يتطلب التطبيق المباشر صلاحية التغذية وخطة مخصصة منشورة. يمكنك إعداد مسودة أولاً.')}</p>`:''}${!editor&&canApply?`<p class="caption">${rt('Creates and assigns an individual copy for','ينشئ نسخة فردية ويخصصها لـ')} <strong data-no-translate>${e(c.name)}</strong>.</p>`:''}`;
 U.enhance($('#calculator-result'));
}
async function applyCalorieResult(asDraft=false){
 if(!coach()||!calorieResult)throw Error('Calculate the estimate first.');const f=$('[data-form="calculator"]');
 if(!f||calorieResult.signature!==JSON.stringify(Object.fromEntries(new FormData(f)))||calorieClientId!==calorieResult.clientId)throw Error('Inputs changed. Calculate again before applying.');
 const result=calorieResult;
 if(editor){PandaCalories.updatePlan(editor.data,result);dirty=true;U.close();render();calorieResult=null;return;}
 const c=get('clients',result.clientId),p=c&&get('nutrition_plans',c.nutrition_id);if(!c||!p)throw Error('Choose a client with a nutrition plan.');
 if(JSON.stringify(c)!==result.originalProfile||JSON.stringify(p)!==result.originalPlan)throw Error('The client or plan changed. Reopen the calculator.');
 const draft=copy(p);draft.id=S.id('nutrition');draft.name=(c.name+' · '+rt('Nutrition targets','أهداف التغذية')).slice(0,120);delete draft.name_ar;draft.version=asDraft?0:1;draft.versions=[];draft.status=asDraft?'draft':'published';PandaCalories.updatePlan(draft,result);
 if(asDraft){editor={type:'nutrition_plans',data:draft};dirty=true;calorieResult=null;U.close();location.hash='/editor';if(route==='editor')render();U.toast(rt('Individual draft opened. Review, publish and assign it in Clients.','تم فتح مسودة فردية. راجعها وانشرها وخصصها في العملاء.'),'info');return;}
 const apply=f.querySelector('[data-action="apply-calories"]');if(apply)apply.disabled=true;
 try{await S.commit(s=>{const current=s.clients.find(x=>x.id===result.clientId),plan=current&&s.nutrition_plans.find(x=>x.id===current.nutrition_id);if(!current||JSON.stringify(current)!==result.originalProfile||JSON.stringify(plan)!==result.originalPlan)throw Error('The client or plan changed. Reopen the calculator.');if(!s.packages.find(x=>x.id===current.package_id)?.features.includes('nutrition')||plan.status!=='published')throw Error('A published nutrition plan and nutrition access are required.');s.nutrition_plans.push(draft);current.nutrition_id=draft.id;},'Applied individual calorie and macro targets');calorieResult=null;U.close();render();U.toast(rt('Calorie and macro targets saved for','تم حفظ أهداف السعرات والمغذيات لـ')+' '+c.name+'.');}finally{if(apply?.isConnected)apply.disabled=false;}
}
function invalidateCalorieResult(){calorieResult=null;const out=$('#calculator-result');if(out)out.innerHTML='';}
function calorieInputChanged(el){if(!el.closest?.('[data-form="calculator"]'))return;if(el.name==='goal'){const presets={loss:-20,maintain:0,gain:10};if(Object.hasOwn(presets,el.value))$('[data-form="calculator"] [name="adjust"]').value=presets[el.value];}if(el.name==='adjust'){const goal=$('[data-form="calculator"] [name="goal"]');goal.value='custom';U.enhance($('#calorie-fields'));}invalidateCalorieResult();}

function educationContent(){
 const allRecords=state.articles.filter(a=>a.status==='published'&&!a.hidden),query=educationQuery.trim().toLowerCase();
 const records=allRecords.filter(a=>(!educationCategory||learningGroup(a)===educationCategory)&&(!query||[a.title,a.summary,...a.sections.map(x=>x[0]),...Object.values(articleLocale(a,true)).filter(x=>typeof x==='string'),...articleLocale(a,true).sections.map(x=>x[0])].join(' ').toLowerCase().includes(query)));
 const first=!educationCategory&&!educationExpanded&&!query?['hub-nutrition','hub-training','hub-supplements'].map(id=>records.find(a=>a.id===id)).filter(Boolean):records;
 const groups=window.PANDA_EDUCATION_095;
 return `<div class="education-content"><div class="education-hub-intro panel section"><div><span class="eyebrow">LEARN · APPLY · REVIEW</span><h2>Knowledge for the life you actually live.</h2><p class="muted">${recipeLanguage()?`${allRecords.length} دليلاً منشوراً في ${groups.length} موضوعاً. اختر موضوعاً أو ابحث في عناوين الفصول.`:`${allRecords.length} published guides across ${groups.length} topics. Choose a topic or search the chapter headings.`}</p></div><form data-form="education-search" class="education-search">${field('Search guides and topics','query',educationQuery,'search','maxlength="150" placeholder="e.g. RIR, Ramadan, fiber…"')}<button type="submit" class="btn primary">${icon('search')} Search</button></form></div><section class="section" aria-label="Learning topics"><div class="learning-categories coaching-learning-categories">${groups.map(g=>{const count=allRecords.filter(a=>learningGroup(a)===g.category).length;return `<button type="button" class="learning-category ${educationCategory===g.category?'selected':''}" aria-pressed="${educationCategory===g.category}" data-action="education-category" data-category="${e(g.category)}">${img(articleImage(allRecords.find(a=>a.id===g.id)||g),articleLocale(g).title)}<span class="learning-category-icon">${icon(g.icon)}</span><strong>${e(g.category)}</strong><span class="learning-count">${articleCountLabel(count)} ${icon('arrow')}</span></button>`;}).join('')}</div></section><section class="panel featured-learning section" aria-labelledby="education-results-title"><div class="panel-head"><h2 id="education-results-title" tabindex="-1">${e(educationCategory||(!educationExpanded&&!query?'Start here':'All articles'))} <span class="tag" data-education-count="${first.length}">${first.length}</span></h2><button type="button" class="text-link" data-action="education-all">${rt('All guides','كل الأدلة')} (${allRecords.length}) ${icon('arrow')}</button></div>${query?`<p class="caption">${rt('Search','البحث')}: ${e(educationQuery)} · ${articleCountLabel(records.length)}</p>`:''}<div class="education-grid">${first.map(a=>learningCard(a)).join('')||empty('No guides match this selection','Choose another topic or clear the search.')}</div></section>${first.length<records.length?`<div class="actions section">${btn('education-all',rt('Browse all guides','تصفح كل الأدلة')+' ('+allRecords.length+')',true)}</div>`:''}</div>`;
}

document.addEventListener('change',async event=>{
 const el=event.target;
 try{
  if(el.hasAttribute('data-supplement-client')){await S.commit(s=>s.preferences.client_id=el.value,'Selected client supplement plan');render();}
  if(el.hasAttribute('data-calculator-client')){calorieClientId=el.value;const c=get('clients',el.value)||{};$('#calorie-fields').innerHTML=calorieFields(c);$('#calorie-context').innerHTML=calorieContext(c);const f=$('[data-form="calculator"]');f.elements.namedItem('suitable').checked=false;invalidateCalorieResult();U.enhance($('#calorie-fields'));}else calorieInputChanged(el);
 }catch(err){U.toast(err.message,'error');}
});
document.addEventListener('input',event=>{
 if(event.target.name!=='calculator_client')calorieInputChanged(event.target);
 if(event.target.dataset.path?.endsWith('.effort_scale')&&editor){const path=event.target.dataset.path.replace(/effort_scale$/,'effort_target');if(!event.target.value){setPath(editor.data,path,null);const target=document.querySelector('[data-path="'+path+'"]');if(target)target.value='';}}
});

/* Catalogue authorship, bilingual reading and inline assignments. */
let studioArticle=null,studioExercise=null,studioPhotoBusy=false,activeArticleId=null;
const studioT=(en,ar)=>rt(en,ar);
function articleLocale(a,arabic=recipeLanguage()){
 if(!arabic)return {...a};const tr=x=>PandaI18n.translate(x);
 return {...a,title:a.title_ar||tr(a.title),summary:a.summary_ar||tr(a.summary),category:a.category_ar||tr(a.category),sections:a.sections.map(([h,b],i)=>[a.sections_ar?.[i]?.[0]||tr(h),a.sections_ar?.[i]?.[1]||tr(b)])};
}
function chosenPhoto(variants){const gender=PandaExperience.get().imagery;return variants?.[gender]||variants?.neutral||'';}
function chapterPhoto(a,i){const p=chosenPhoto(a.photos?.chapters?.[i]);return p?`<figure class="studio-chapter-photo">${img(p,articleLocale(a).sections[i]?.[0]||articleLocale(a).title)}<figcaption>${e(articleLocale(a).sections[i]?.[0]||'')}</figcaption></figure>`:'';}
function photoControls(kind){return `<section class="panel studio-photos section"><h3>${rt('Photographs','الصور')}</h3><p class="caption">${kind==='exercise'?rt('Every exercise should carry two photographs: one Male and one Female version. Clients see the version that matches the athlete imagery they chose.','ينبغي أن يحمل كل تمرين صورتين: نسخة للرجال وأخرى للنساء. يرى العميل النسخة المطابقة لاختياره.'):rt('Upload a shared photo or separate Male / Female versions. Images are saved with this entry.','ارفع صورة مشتركة أو نسختين للرجال والنساء. تُحفظ الصور مع هذا الإدخال.')}</p><div class="studio-photo-summary section" data-studio-photo-summary></div><div class="form-grid section">${kind==='article'?select(rt('Photo placement','موضع الصورة'),'studio-photo-placement','cover',[['cover',rt('Article cover','غلاف المقال')],...Array.from({length:Math.max(1,studioArticle?.sections?.length||1)},(_,i)=>['chapter:'+i,rt('After chapter ','بعد الفصل ')+(i+1)])],'data-studio-photo-location'):''}${select(rt('Image variant','نسخة الصورة'),'studio-photo-variant',kind==='exercise'?'male':'neutral',[['neutral',rt('Shared / neutral','مشتركة / محايدة')],['male',rt('Male','رجال')],['female',rt('Female','نساء')]],'data-studio-photo-location')}</div><div class="studio-photo-preview section" data-studio-photo-preview></div><div class="actions section"><label class="btn">${icon('upload')} ${rt('Upload photograph','رفع صورة')}<input class="studio-file" type="file" accept="image/jpeg,image/png,image/webp" data-studio-upload="${kind}"></label>${btn('studio-photo-remove',rt('Remove selected photo','إزالة الصورة المختارة'))}</div><p class="caption" role="status" data-studio-photo-status>${rt('JPG, PNG or WebP · up to 12 MB. Optimised automatically.','JPG أو PNG أو WebP حتى ١٢ ميغابايت. تُضغط تلقائياً.')}</p></section>`;}
function photoTarget(){const a=studioArticle&&$('[data-form="article"]'),obj=a?studioArticle:studioExercise;if(!obj)return null;const variant=$('[name="studio-photo-variant"]')?.value||'neutral',place=a?($('[name="studio-photo-placement"]')?.value||'cover'):'cover';obj.photos??=a?{cover:{},chapters:{}}:{};let target;if(!a)target=obj.photos;else if(place==='cover')target=obj.photos.cover??={};else target=(obj.photos.chapters??={})[place.split(':')[1]]??={};return {target,variant,obj};}
function photoPairState(photos={}){return {male:!!photos.male,female:!!photos.female,neutral:!!photos.neutral,complete:!!(photos.male&&photos.female),any:!!(photos.male||photos.female||photos.neutral)};}
function photoSummary(p){
 if(!p)return '';
 const isExercise=!!studioExercise,base=isExercise?PANDA_CATALOGUE.find(c=>c.exercise_id===studioExercise.exercise_id)?.image_url||'':'',pair=photoPairState(p.target);
 const tiles=[['male',rt('Male','رجال')],['female',rt('Female','نساء')],['neutral',rt('Shared','مشتركة')]].map(([k,label])=>{const has=!!p.target[k];return `<button type="button" class="studio-photo-tile ${p.variant===k?'is-active':''} ${has?'has-photo':'is-empty'}" data-action="studio-photo-variant" data-variant="${k}" aria-pressed="${p.variant===k}"><span class="studio-photo-thumb">${has?img(p.target[k],label):icon('upload')}</span><span class="studio-photo-tile-label"><strong>${e(label)}</strong><small>${has?rt('Uploaded','مرفوعة'):rt('Not set','غير محددة')}</small></span></button>`;}).join('');
 let note='';
 if(isExercise)note=pair.complete?`<p class="caption studio-photo-note is-ok">${icon('check')} ${rt('Both versions are set.','النسختان محددتان.')}</p>`:`<p class="caption studio-photo-note is-warn">${icon('info')} ${rt('Recommended: upload one Male and one Female photograph.','يُفضل رفع صورة للرجال وأخرى للنساء.')}${!pair.any&&base?' '+rt('Until then the supplied catalogue photograph is used.','حتى ذلك الحين تُستخدم صورة الكتالوج المرفقة.'):''}</p>`;
 return `<div class="studio-photo-tiles" role="group" aria-label="${rt('Photo versions','نسخ الصورة')}">${tiles}</div>${note}`;
}
function photoPreview(){const p=photoTarget(),node=$('[data-studio-photo-preview]'),summary=$('[data-studio-photo-summary]');if(summary)summary.innerHTML=photoSummary(p);if(node)node.innerHTML=p?.target[p.variant]?img(p.target[p.variant],rt('Selected photo preview','معاينة الصورة المختارة')):`<p class="caption">${rt('No upload for this variant. The shared photo or existing illustration will be used.','لا توجد صورة مرفوعة لهذه النسخة. ستُستخدم الصورة المشتركة أو الصورة الحالية.')}</p>`;}
async function studioUpload(file){if(!file)return;const p=photoTarget();if(!p)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>12*1024*1024)throw Error(rt('Choose JPG, PNG or WebP up to 12 MB.','اختر JPG أو PNG أو WebP حتى ١٢ ميغابايت.'));studioPhotoBusy=true;const status=$('[data-studio-photo-status]');status.textContent=rt('Optimising photograph…','جار تحسين الصورة…');try{const bitmap=await createImageBitmap(file);if(bitmap.width<100||bitmap.height<100){bitmap.close();throw Error('Choose an image at least 100 × 100 pixels.');}let size=Math.min(1,1200/Math.max(bitmap.width,bitmap.height)),result;for(let attempt=0;attempt<5;attempt++){const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*size));canvas.height=Math.max(1,Math.round(bitmap.height*size));const ctx=canvas.getContext('2d');ctx.fillStyle='#10191a';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);for(const q of [.84,.72,.6,.48]){result=canvas.toDataURL('image/jpeg',q);if(result.length<=180000)break;}if(result.length<=180000)break;size*=.75;}bitmap.close();if(!PandaStudio.validPhoto(result))throw Error('Choose a smaller image.');if(p.obj!==(p.obj===studioArticle?studioArticle:studioExercise))return;p.target[p.variant]=result;photoPreview();status.textContent=rt('Photo ready. Save the entry to keep it.','الصورة جاهزة. احفظ الإدخال للاحتفاظ بها.');}finally{studioPhotoBusy=false;}}
function studioArticleEditor(id){if(!coach())throw Error('Coach view required.');const a=id?copy(get('articles',id)):{id:S.id('article'),title:'',category:'Coaching',summary:'',sections:[['','']],status:'draft',image:'',origin:'Coach-created content',version:0};if(!a)throw Error('Article not found.');studioArticle=a;studioExercise=null;const ar=articleLocale(a,true),body=sections=>sections.map(x=>x[0]+'\n'+x[1]).join('\n\n---\n\n');U.modal(id?'Edit education article':'Create education article',form('article',`<div class="stack"><div class="form-grid">${field('Title','title',a.title,'text','required maxlength="160" dir="ltr"')}${field(rt('Arabic title','العنوان العربي'),'title_ar',a.title_ar||((ar.title!==a.title)?ar.title:''),'text','maxlength="160" dir="rtl"')}${field('Category','category',a.category,'text','required maxlength="80"')}${field(rt('Arabic category','الفئة بالعربية'),'category_ar',a.category_ar||((ar.category!==a.category)?ar.category:''),'text','maxlength="80" dir="rtl"')}${select('Publication status','status',a.status,[['draft','Draft'],['published','Published']])}</div>${area('Summary','summary',a.summary,'required maxlength="600" dir="ltr"')}${area(rt('Arabic summary','الملخص بالعربية'),'summary_ar',a.summary_ar||((ar.summary!==a.summary)?ar.summary:''),'maxlength="600" dir="rtl"')}<p class="caption">${rt('One chapter: heading on the first line, then body text. Separate chapters with --- on its own line. Keep both language versions aligned.','لكل فصل: العنوان في السطر الأول ثم النص. افصل الفصول بسطر يحتوي على --- فقط. حافظ على تطابق ترتيب النسختين.')}</p>${area('Article sections — put --- on its own line between chapters; first line is the heading','body',body(a.sections),'required rows="12" maxlength="100000" dir="ltr"')}${area(rt('Arabic chapters','الفصول بالعربية'),'body_ar',a.sections_ar?.length?body(a.sections_ar):ar.sections.some((x,i)=>x[1]!==a.sections[i][1])?body(ar.sections):'','rows="12" maxlength="100000" dir="rtl"')}${photoControls('article')}</div>${actions('Save article')}`,a.id));photoPreview();}
function parseChapters(body,required=true){if(!body.trim()){if(required)throw Error('Add a chapter heading and text.');return [];}const parts=body.trim().split(/\n[ \t]*---[ \t]*\n/).map(s=>{const lines=s.trim().split('\n');return [lines.shift().trim(),lines.join('\n').trim()];});if(parts.some(x=>!x[0]||!x[1]))throw Error('Each chapter needs a heading and body text.');return parts;}
async function studioSaveArticle(d){if(!coach()||!studioArticle)throw Error('Reopen the article.');if(studioPhotoBusy)throw Error('Wait for the photograph to finish.');const a=copy(studioArticle),sections=parseChapters(d.body),ar=parseChapters(d.body_ar||'',false);if(ar.length&&ar.length!==sections.length)throw Error(rt('English and Arabic must contain the same number of chapters.','يجب أن تتضمن النسختان العدد نفسه من الفصول.'));if(d.status==='published'&&(!d.title_ar?.trim()||!d.summary_ar?.trim()||ar.length!==sections.length))throw Error(rt('Complete both languages before publishing. You can save an unfinished translation as a draft.','أكمل اللغتين قبل النشر. يمكنك حفظ الترجمة غير المكتملة كمسودة.'));for(const k of Object.keys(a.photos?.chapters||{}))if(Number(k)>=sections.length)delete a.photos.chapters[k];await S.entity('articles',{...a,title:d.title,category:d.category,summary:d.summary,title_ar:d.title_ar||'',category_ar:d.category_ar||'',summary_ar:d.summary_ar||'',sections,sections_ar:ar,status:d.status,version:(a.version||0)+1});studioArticle=null;activeArticleId=null;}
