async function studioSaveExercise(d,id){if(!coach()||studioExercise?.exercise_id!==id)throw Error('Reopen the exercise.');if(studioPhotoBusy)throw Error('Wait for the photograph to finish.');const split=s=>s.split(',').map(x=>x.trim()).filter(Boolean),original=PANDA_CATALOGUE.some(x=>x.exercise_id===id),previous=S.get().exercise_edits[id]||{},x={...previous,exercise_id:id,name:d.name,name_ar:d.name_ar||'',description:d.description||'',description_ar:d.description_ar||'',primary_muscle:d.primary_muscle,secondary_muscles:split(d.secondary_muscles),muscle_groups:split(d.muscle_groups),equipment:d.equipment,difficulty:d.difficulty,category:d.category,tags:split(d.tags),biomechanics_cue:d.biomechanics_cue,instructions:d.instructions.split('\n').map(x=>x.trim()).filter(Boolean),instructions_ar:(d.instructions_ar||'').split('\n').map(x=>x.trim()).filter(Boolean),photos:copy(studioExercise.photos||{}),review_status:d.reviewed?'coach_reviewed':'needs_coach_review',...(original?{}:{image_url:'',image_kind:'exercise'})};await S.commit(s=>{s.exercise_edits[id]=x;},original?'Updated exercise reference':'Created exercise');studioExercise=null;const pair=photoPairState(x.photos);if(pair.complete)return '';return pair.any?rt('Saved. One gendered photograph is still missing — add both Male and Female so every client sees a matching image.','تم الحفظ. ما زالت إحدى الصورتين ناقصة — أضف نسخة الرجال ونسخة النساء ليرى كل عميل صورة مطابقة.'):original?'':rt('Saved. Add a Male and a Female photograph so every client sees a matching image.','تم الحفظ. أضف صورة للرجال وأخرى للنساء ليرى كل عميل صورة مطابقة.');}
function studioReferences(){const refs=new Map(PandaCoaching.catalogue.map(x=>[x.id,x]));for(const x of state.supplement_references||[])refs.set(x.id,x);return [...refs.values()];}
function supplementTemplateBegin(id){if(!coach())throw Error('Coach view required.');const t=id?get('supplement_templates',id):null;supplementDraft={templateId:t?.id||S.id('supp_template'),name:t?.name||'',name_ar:t?.name_ar||'',summary:t?.summary||'',summary_ar:t?.summary_ar||'',notes:t?.notes||'',notes_ar:t?.notes_ar||'',status:t?.status||'draft',items:copy(t?.items||[]),original:t?JSON.stringify(t):null};supplementEditor();}

async function supplementTemplateSave(f){if(!coach()||!supplementDraft?.templateId)throw Error('Open a template first.');if(!f.reportValidity())return;supplementCapture();const d=copy(supplementDraft),old=get('supplement_templates',d.templateId);if((old?JSON.stringify(old):null)!==d.original)throw Error('This template changed. Reopen it before saving.');await S.entity('supplement_templates',{...old,id:d.templateId,name:d.name.trim(),name_ar:d.name_ar||'',summary:d.summary,summary_ar:d.summary_ar,notes:d.notes,notes_ar:d.notes_ar,status:d.status,items:d.items,version:(old?.version||0)+1});supplementDraft=null;U.close();render();U.toast(rt('Template saved. Existing client copies are unchanged.','حُفظ القالب. لم تتغير نسخ العملاء الحالية.'));}
