document.addEventListener('click',async event=>{const target=event.target,button=target.closest('[data-action]');if(button&&!button.disabled){event.preventDefault();try{button.disabled=true;button.setAttribute('aria-busy','true');await action(button)}catch(err){U.toast(err.message,'error');const f=$('#modal[open] form')||$('[data-form="editor"]');if(f?.querySelector('.form-error'))f.querySelector('.form-error').textContent=err.message;}finally{button.disabled=false;button.removeAttribute('aria-busy');}}const a=target.closest('a[href^="#/"]');if(a&&$('#modal').open)U.close();});
