document.addEventListener('submit',async event=>{const f=event.target.closest('[data-form]');if(!f)return;event.preventDefault();if(f.dataset.pending)return;const previousError=f.querySelector('.form-error');if(previousError)previousError.textContent='';f.dataset.pending='true';const submit=f.querySelector('[type="submit"]'),label=submit?.innerHTML;if(submit){submit.disabled=true;submit.setAttribute('aria-busy','true');if(S.online)submit.innerHTML=icon('clock')+' Saving…';}try{await saveForm(f)}catch(err){const out=f.querySelector('.form-error');if(out){out.textContent=err.message;out.setAttribute?.('tabindex','-1');out.focus?.({preventScroll:true});out.scrollIntoView?.({block:'nearest',behavior:'auto'});}else U.toast(err.message,'error');}finally{delete f.dataset.pending;if(submit){submit.disabled=false;submit.removeAttribute('aria-busy');submit.innerHTML=label;}}});
document.addEventListener('input',event=>{const el=event.target;recipeUpdateInput(el);if(el.closest?.('[data-form="intake"]')){intakeDirty=true;U.saveState(el.closest('form'),'dirty');}if(el.closest?.('[data-form="checkin"]')){checkinDirty=true;U.saveState(el.closest('form'),'dirty');U.checkinProgress(el.closest('form'));}if(el.dataset.path&&editor){setPath(editor.data,el.dataset.path,el.type==='number'?((el.dataset.path.endsWith('.effort_target')||el.dataset.path.endsWith('.cardio.frequency_per_week'))&&el.value===''?null:Number(el.value)):el.value);dirty=true;U.saveState($('[data-form="editor"]'),'dirty');if(editor.type==='nutrition_plans'){const match=el.dataset.path.match(/^variants\.(\d+)\.meals\.(\d+)\./);if(match)detachRecipeMeal(editor.data.variants[match[1]].meals[match[2]]);editor.data.variants.forEach((v,i)=>{const out=$(`[data-total="${i}"]`);if(out)out.innerHTML=macro(S.totals(v.meals.flatMap(m=>m.items)));v.meals.forEach((m,j)=>{const output=$(`[data-meal-total="${i}-${j}"]`);if(output)output.innerHTML=macro(S.totals(m.items));});});}}if(el.hasAttribute('data-picker-search'))pickerResults(el.value);if(el.hasAttribute('data-recipe-meal-search')){const q=el.value.trim().toLowerCase(),out=$('#recipe-meal-results');if(out)out.innerHTML=recipeMealRows(state.recipes.filter(r=>r.status==='published'&&[r.name,r.name_ar||'',...r.tags].join(' ').toLowerCase().includes(q)),recipeMealIndex);}if(el.dataset.tableSearch){const container=$('#'+el.dataset.tableSearch),rows=[...container.querySelectorAll('tbody tr')];let visible=0;rows.forEach(tr=>{tr.hidden=!tr.textContent.toLowerCase().includes(el.value.trim().toLowerCase());if(!tr.hidden)visible++;});let result=container.querySelector('.table-filter-result');if(!result){result=document.createElement('p');result.className='caption table-filter-result';result.setAttribute('role','status');container.append(result);}result.textContent=visible?visible+' of '+rows.length+' records shown':'No records match your search.';}});
document.addEventListener('change',async event=>{const el=event.target;try{if(el.closest?.('[data-form="intake"]')){intakeDirty=true;U.saveState(el.closest('form'),'dirty');PandaIntake.sync(el);return;}if(el.dataset.mealUpload!==undefined){await mealPhotoUpload(el);return;}if(el.dataset.recipePath){recipeUpdateInput(el);return;}if(el.hasAttribute('data-recipe-upload')){await recipeImageUpload(el.files[0]);return;}if(el.hasAttribute('data-recipe-plan-client')){recipePlaceModal(recipePlaceContext.id,el.value);return;}if(el.hasAttribute('data-recipe-plan-variant')){const p=get('nutrition_plans',get('clients',recipePlaceContext.cid).nutrition_id);$('#recipe-plan-slot').innerHTML=recipeSlotSelect(p,Number(el.value));U.enhance($('#recipe-plan-slot'));return;}if(el.name==='muscle'&&el.closest('[data-form="library-search"]')){await saveForm(el.closest('form'));return;}if(el.dataset.control){if((dirty||checkinDirty||recipeDirty)&&['role','client'].includes(el.dataset.control)&&!confirm('Discard the unsaved changes and switch workspace?')){el.value=el.dataset.control==='role'?state.preferences.role:client().id;U.enhance(el.closest('.modal-body')||$('#main'));return;}if(el.dataset.control==='favorites'){const f=$('[data-form="library-search"]');filters={...filters,...(f?Object.fromEntries(new FormData(f)):{}),favorites:el.checked,page:1};updateLibrary();return;}if(el.dataset.control==='hidden-exercises'){if(!coach())throw Error('Coach view required.');const f=$('[data-form="library-search"]');filters={...filters,...(f?Object.fromEntries(new FormData(f)):{}),hidden:el.checked,page:1};updateLibrary();return;}await S.commit(s=>{if(el.dataset.control==='role')s.preferences.role=el.value;if(el.dataset.control==='client')s.preferences.client_id=el.value;if(el.dataset.control==='motion')s.preferences.reduced_motion=el.checked;},'Updated demo preferences');if(['role','client'].includes(el.dataset.control)){dirty=false;checkinDirty=false;recipeDirty=false;recipeDraft=null;recipeUpload=null;editor=null;dayIndex=variantIndex=0;U.close();location.hash='/'+(S.get().preferences.role==='coach'?'coach':'dashboard');}render();}
if(el.dataset.onboarding){await S.commit(s=>s.clients.find(c=>c.id===client().id).onboarding[el.dataset.onboarding]=el.checked,'Updated onboarding checklist');render();}
if(el.dataset.upload==='backup'){if(S.online&&PandaCloud.account.role!=='coach')throw Error('Only the coach can restore account data.');const f=el.files[0];if(!f)return;if(f.size>8*1024*1024)throw Error('This backup is too large (maximum 8 MB).');U.toast('Reading backup…','info');const data=PandaRecipes.migrate(JSON.parse(await f.text()));S.validate(data);window._pendingPandaRestore=data;U.modal('Restore this backup?',`<p>${S.online?'Restore portal records for these existing accounts. Sign-in credentials remain unchanged.':'This will replace the data currently saved in this browser.'}</p>${info([['Demo clients',data.clients.length],['Training plans',data.programs.length],['Nutrition plans',data.nutrition_plans.length],['Check-ins',data.checkins.length],['Progress photos',data.photos.length]])}<div class="actions section">${btn('backup-restore',S.online?'Restore account data':'Replace local data',true)}${btn('close','Cancel')}</div>`);el.value='';}
}catch(err){U.toast(err.message,'error');if(el.dataset.control==='role')el.value=state.preferences.role;else if(el.dataset.control==='client')el.value=client().id;else if(el.dataset.control==='motion')el.checked=!!state.preferences.reduced_motion;else if(el.dataset.control==='hidden-exercises')el.checked=!!filters.hidden;else if(el.dataset.onboarding)el.checked=client().onboarding[el.dataset.onboarding];else el.value='';U.enhance(el.closest('.modal-body')||$('#main'));}});
